3	export const ERROR_CODES = {
4	  E_UNKNOWN_SKU: "unknown sku",
5	  E_EMPTY_CART: "cart is empty",
6	  E_USAGE: "usage: cartctl add <sku> <qty>",
7	} as const;
8	
9	export type ErrorCode = keyof typeof ERROR_CODES;
10	
11	export class CliError extends Error {
12	  readonly code: string;
13	  constructor(code: string, message: string) {
14	    super(message);
15	    this.name = "CliError";
16	    this.code = code;
17	  }
18	}
19	
20	export function fail(code: string, message?: string): never {
21	  if (!(code in ERROR_CODES)) throw new Error(`unregistered error code ${code}`);
22	  throw new CliError(code, message ?? ERROR_CODES[code as ErrorCode]);
23	}
